Let's write code:

function decodeUtf8(bytes) {
  if (!Array.isArray(bytes)) return null;
  for (let i = 0; i < bytes.length; i++) {
    const b = bytes[i];
    if (!Number.isInteger(b) || b < 0 || b > 255) return null;
  }
  const result = [];
  let codePoint = 0;
  let bytesNeeded = 0;
  let bytesSeen = 0;
  let lower = 0x80;
  let upper = 0xBF;
  let i = 0;
  const len = bytes.length;
  while (i < len) {
    const b = bytes[i];
    if (bytesNeeded === 0) {
      if (b <= 0x7F) {
        result.push(b);
        i++;
      } else if (b >= 0xC2 && b <= 0xDF) {
        bytesNeeded = 1;
        codePoint = b & 0x1F;
        i++;
      } else if (b >= 0xE0 && b <= 0xEF) {
        if (b === 0xE0) lower = 0xA0;
        else if (b === 0xED) upper = 0x9F;
        bytesNeeded = 2;
        codePoint = b & 0x0F;
        i++;
      } else if (b >= 0xF0 && b <= 0xF4) {
        if (b === 0xF0) lower = 0x90;
        else if (b === 0xF4) upper = 0x8F;
        bytesNeeded = 3;
        codePoint = b & 0x07;
        i++;
      } else {
        result.push(0xFFFD);
        i++;
      }
    } else {
      if (b >= lower && b <= upper) {
        lower = 0x80;
        upper = 0xBF;
        codePoint = (codePoint << 6) | (b & 0x3F);
        bytesSeen++;
        i++;
        if (bytesSeen === bytesNeeded) {
          result.push(codePoint);
          codePoint = 0;
          bytesNeeded = 0;
          bytesSeen = 0;
        }
      } else {
        result.push(0xFFFD);
        codePoint = 0;
        bytesNeeded = 0;
        bytesSeen = 0;
        lower = 0x80;
        upper = 0xBF;
        // do not i++
      }
    }
  }
  if (bytesNeeded !== 0) {
    result.push(0xFFFD);
  }
  return result;
}

